-- Forever (Classic 1.60): русские тексты, задания
-- В текстах вместо макросов имени игрока ($n/$N), класса ($c) и расы ($r) были вписаны конкретные слова
-- (имя персонажа, с которого снимали текст; «Воин», «человек» и т. п. внутри |3-N(...)). Макросы возвращены.
-- Можно запускать повторно.

UPDATE `quest_offer_reward_locale` SET `RewardText` = REGEXP_REPLACE(`RewardText`, '(?<![\\p{L}\\p{N}$|''_-])Makky(?![\\p{L}\\p{N}''_-])', '\\$n')
WHERE locale = 'ruRU' AND `RewardText` NOT REGEXP '[$][nN]' AND `ID` IN (94793,94864);
